import {algorithms,solve,makeMap,validateMap} from './engine.js';
const $=s=>document.querySelector(s),board=$('#board');let map=makeMap(),tool='wall',result=null,index=0,playing=false,timer=null,bench=null,dragging=false,focus=0,toastTimer;
for(const [key,a] of Object.entries(algorithms)){const o=document.createElement('option');o.value=key;o.textContent=a.name;$('#algorithm').append(o);}
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4000);}
function tab(name){document.querySelectorAll('.tab').forEach(e=>e.hidden=e.id!==name);document.querySelectorAll('[data-tab]').forEach(e=>{e.classList.toggle('active',e.dataset.tab===name);e.setAttribute('aria-current',e.dataset.tab===name?'page':'false');});history.replaceState(null,'','#'+name);requestAnimationFrame(fitGrid);}
for(const e of document.querySelectorAll('[data-tab]'))e.onclick=()=>tab(e.dataset.tab);
$('.brand').onclick=e=>{e.preventDefault();tab('lab');};
function stop(){clearTimeout(timer);playing=false;$('#run').textContent=result&&index<result.visited.length?'▶ Resume search':'▶ Run algorithm';}
function clearSearch(invalidate=false){stop();result=null;index=0;$('#run').textContent='▶ Run algorithm';for(const id of ['explored','steps','cost','time'])$('#'+id).textContent='—';$('#status').textContent='Ready to explore';$('#traceText').textContent='Run or step through a search to inspect the current expansion.';if(invalidate){bench=null;$('#results').innerHTML='<tr><td colspan="6">Map changed. Run a new comparison.</td></tr>';$('#comparisonNote').textContent='Your map changed. Run all five algorithms again for a fair comparison.';}render();explain();}
function build(){board.innerHTML='';board.style.gridTemplateColumns=`repeat(${map.cols},1fr)`;board.setAttribute('aria-rowcount',map.rows);board.setAttribute('aria-colcount',map.cols);focus=Math.min(focus,map.cells.length-1);map.cells.forEach((_,i)=>{const c=document.createElement('div');c.dataset.i=i;c.className='cell';c.setAttribute('role','gridcell');c.tabIndex=i===focus?0:-1;board.append(c);});$('#dimensions').textContent=`${map.cols} × ${map.rows}`;render();requestAnimationFrame(fitGrid);}
function render(){const visited=new Set(result?.visited.slice(0,index)||[]),done=result&&index>=result.visited.length,path=new Set(done?result.path:[]),current=result?.visited[index-1];for(let i=0;i<map.cells.length;i++){const c=board.children[i];if(!c)continue;const kind=i===map.start?'start':i===map.goal?'goal':map.cells[i]===-1?'wall':map.cells[i]===5?'weight':'';c.className='cell '+kind+(visited.has(i)?' visited':'')+(path.has(i)?' path':'')+(i===current?' current':'');c.textContent=i===map.start?'S':i===map.goal?'G':map.cells[i]===5?'5':'';c.setAttribute('aria-label',`Row ${Math.floor(i/map.cols)+1}, column ${i%map.cols+1}: ${kind||'open'}${path.has(i)?', route':visited.has(i)?', explored':''}`);}}
function explain(){const a=algorithms[$('#algorithm').value];$('#algoTag').textContent=a.tag;$('#formula').textContent=a.formula;$('#insightTitle').textContent=a.name+' · '+a.formula;$('#insightText').textContent=a.description;}
function metrics(){const done=index>=result.visited.length;$('#explored').textContent=index;$('#steps').textContent=done?(result.steps??'No route'):'—';$('#cost').textContent=done?(result.cost??'—'):'—';$('#time').textContent=done?result.time.toFixed(2)+' ms':'—';$('#status').textContent=done?(result.found?'Route found':'No route exists'):playing?'Exploring…':'Paused · step '+index;const n=result.trace[index-1];if(n)$('#traceText').textContent=`Expanded (${Math.floor(n.id/map.cols)+1}, ${n.id%map.cols+1}) · g = ${n.g} · h = ${n.h} · g + h = ${n.f}. ${algorithms[result.type].name} selects using: ${algorithms[result.type].formula}.`;if(done){stop();$('#insightText').textContent=result.found?`${algorithms[result.type].name} explored ${result.visited.length} cells and found a ${result.steps}-step route costing ${result.cost}. ${algorithms[result.type].description}`:'The search exhausted all reachable cells without reaching the goal. Remove a wall or move an endpoint, then try again.';}}
function ensureResult(){revealGrid();if(!result||index>=result.visited.length){result=solve(map,$('#algorithm').value);index=0;}}
function tick(){if(!playing)return;index=Math.min(result.visited.length,index+Math.max(1,Math.floor(Number($('#speed').value)/12)));render();metrics();if(playing)timer=setTimeout(tick,Math.max(10,140-Number($('#speed').value)*1.25));}
$('#run').onclick=()=>{if(playing){stop();metrics();return;}ensureResult();playing=true;$('#run').textContent='Ⅱ Pause search';tick();};
$('#step').onclick=()=>{stop();ensureResult();index++;render();metrics();$('#run').textContent=index<result.visited.length?'▶ Resume search':'▶ Run algorithm';};
$('#clear').onclick=()=>clearSearch();$('#algorithm').onchange=()=>clearSearch();$('#speed').oninput=()=>$('#speedLabel').textContent=Number($('#speed').value)<35?'Slow':Number($('#speed').value)<70?'Medium':'Fast';
$('#preset').onchange=()=>{map=makeMap($('#preset').value,$('#preset').value==='random'?Date.now():42);build();clearSearch(true);};
for(const b of document.querySelectorAll('[data-tool]'))b.onclick=()=>{tool=b.dataset.tool;document.querySelectorAll('[data-tool]').forEach(e=>{e.classList.toggle('selected',e===b);e.setAttribute('aria-pressed',String(e===b));});};
function paint(i){if(!Number.isInteger(i)||i<0||i>=map.cells.length)return;if(tool==='start'&&i!==map.goal){map.start=i;map.cells[i]=1;}else if(tool==='goal'&&i!==map.start){map.goal=i;map.cells[i]=1;}else if(tool!=='start'&&tool!=='goal'&&i!==map.start&&i!==map.goal)map.cells[i]=tool==='wall'?-1:tool==='weight'?5:1;else return;clearSearch(true);}
board.onpointerdown=e=>{const c=e.target.closest('.cell');if(!c)return;e.preventDefault();dragging=true;paint(Number(c.dataset.i));};board.onpointermove=e=>{if(!dragging)return;const c=document.elementFromPoint(e.clientX,e.clientY)?.closest('.cell');if(c&&board.contains(c))paint(Number(c.dataset.i));};window.addEventListener('pointerup',()=>dragging=false);window.addEventListener('pointercancel',()=>dragging=false);
board.onkeydown=e=>{const c=e.target.closest('.cell');if(!c)return;let i=Number(c.dataset.i),next=i;if(e.key==='ArrowUp')next=i-map.cols;else if(e.key==='ArrowDown')next=i+map.cols;else if(e.key==='ArrowLeft'&&i%map.cols>0)next=i-1;else if(e.key==='ArrowRight'&&i%map.cols<map.cols-1)next=i+1;else if(e.key===' '||e.key==='Enter'){e.preventDefault();paint(i);return;}else return;e.preventDefault();if(next>=0&&next<map.cells.length){board.children[focus].tabIndex=-1;focus=next;board.children[next].tabIndex=0;board.children[next].focus();}};
function compare(){stop();bench=Object.keys(algorithms).map(type=>{solve(map,type);const runs=Array.from({length:15},()=>solve(map,type)),r=runs[0];return {...r,time:runs.map(r=>r.time).sort((a,b)=>a-b)[7]};});const optimal=bench.find(r=>r.type==='dijkstra').cost;$('#results').innerHTML=bench.map(r=>`<tr><td>${algorithms[r.type].name}</td><td>${r.found?'Found':'Unreachable'}</td><td>${r.visited.length}</td><td>${r.steps??'—'}</td><td class="${r.found&&r.cost===optimal?'best':''}">${r.cost??'—'}${r.found&&r.cost===optimal?' ✓':''}</td><td>${r.time.toFixed(3)} ms</td></tr>`).join('');$('#comparisonNote').textContent=optimal===null?'All five searches confirmed that the goal is unreachable on this map.':`Minimum route cost: ${optimal}. Checkmarks identify algorithms that achieved this cost on this map; they do not imply a general optimality guarantee.`;tab('compare');}
$('#benchmark').onclick=compare;$('#rerun').onclick=compare;
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#csv').onclick=()=>{if(!bench)return toast('Run a comparison first.');const rows=['algorithm,found,explored,steps,cost,median_ms',...bench.map(r=>[algorithms[r.type].name,r.found,r.visited.length,r.steps??'',r.cost??'',r.time.toFixed(4)].join(','))];download('pathmind-benchmark.csv',rows.join('\n'),'text/csv');};
$('#save').onclick=()=>{try{localStorage.setItem('pathmind.map.v1',JSON.stringify(map));toast('Map saved in this browser.');}catch{toast('Browser storage is unavailable. Export your map instead.');}};
$('#load').onclick=()=>{try{const raw=localStorage.getItem('pathmind.map.v1');if(!raw)return toast('No saved map yet.');map=validateMap(JSON.parse(raw));build();clearSearch(true);toast('Saved map loaded.');}catch(e){toast('Could not load map: '+e.message);}};
$('#export').onclick=()=>download('pathmind-map.json',JSON.stringify({version:1,...map},null,2),'application/json');$('#import').onclick=()=>$('#importFile').click();$('#importFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>100000)throw Error('File is too large (100 KB limit).');map=validateMap(JSON.parse(await f.text()));build();clearSearch(true);toast('Map imported.');}catch(e){toast('Invalid map: '+e.message);}finally{$('#importFile').value='';}};
$('#guide').innerHTML=Object.values(algorithms).map(a=>`<article class="guide-card"><h3>${a.name}</h3><code>${a.formula}</code><p>${a.description}</p><small>Optimal: ${a.optimal}</small><small>Frontier: ${a.structure}</small><small>Time: ${a.complexity}</small></article>`).join('');
build();explain();tab(['lab','compare','learn'].includes(location.hash.slice(1))?location.hash.slice(1):'lab');

function fitGrid(){
 const container=$('.board-scroll');if(!container.clientWidth)return;
 const expanded=$('.board-card').classList.contains('expanded');
 const viewport=window.visualViewport?.height||window.innerHeight;
 const height=expanded?container.clientHeight:Math.max(60,Math.min(viewport*.58,viewport-240));
 // Include padding and gaps in the aspect-ratio calculation; fit both axes.
 const css=getComputedStyle(board),pad=parseFloat(css.paddingLeft)+parseFloat(css.paddingRight),gap=parseFloat(css.columnGap)||0;
 const cell=Math.max(0,Math.min((container.clientWidth-pad-gap*(map.cols-1))/map.cols,(height-pad-gap*(map.rows-1))/map.rows));
 board.style.width=`${Math.max(0,cell*map.cols+pad+gap*(map.cols-1))}px`;
}
function revealGrid(){if($('.board-card').classList.contains('expanded'))return;const r=$('.board-card').getBoundingClientRect(),height=window.visualViewport?.height||innerHeight;if(r.top<0||r.bottom>height)$('.board-card').scrollIntoView({block:'start',behavior:'instant'});}
function expandGrid(value){$('.board-card').classList.toggle('expanded',value);document.body.classList.toggle('grid-expanded',value);$('#fitView').textContent=value?'✕ Close expanded view':'⛶ Expand grid';$('#fitView').setAttribute('aria-pressed',String(value));requestAnimationFrame(fitGrid);}
$('#fitView').onclick=()=>expandGrid(!$('.board-card').classList.contains('expanded'));
window.addEventListener('keydown',e=>{if(e.key==='Escape')expandGrid(false);});
$('#gridRun').onclick=()=>$('#run').click();$('#gridStep').onclick=()=>$('#step').click();
new MutationObserver(()=>$('#gridRun').textContent=$('#run').textContent).observe($('#run'),{childList:true,characterData:true,subtree:true});
new ResizeObserver(fitGrid).observe($('.board-scroll'));
window.visualViewport?.addEventListener('resize',fitGrid);window.addEventListener('resize',fitGrid);fitGrid();
